// These constants represent the RISC-V ELF and the image ID generated by risc0-build.
// The ELF is used for proving and the ID is used for verification.
use methods::{DOUBLE_AUCTION_ELF, DOUBLE_AUCTION_ID};
use risc0_zkvm::{default_prover, ExecutorEnv, InnerReceipt, ProverOpts, recursion::identity_p254};
use risc0_zkvm::seal_to_json;
use serde::{Deserialize, Serialize};
use std::env;
use std::fs;


#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Participant {
    pub id: u32,
    pub role: u32,           // 0 = BUY, 1 = SELL
    pub price: u64,          // bid price for buyers, ask price for sellers  
    pub quantity: u64,       // energy quantity to trade
    pub in_coin: u64,        // initial coin balance
    pub in_energy: u64,      // initial energy balance
    pub out_coin: u64,       // final coin balance (after auction)
    pub out_energy: u64,     // final energy balance (after auction)
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct AuctionInput {
    pub participants: Vec<Participant>,
    pub expected_clearing_price: u64,
    pub expected_total_energy_traded: u64,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct PublicJournal {
    pub clearing_price: u64, // TODO: remove this field
    pub in_coin: Vec<u64>,
    pub in_energy: Vec<u64>,
    pub out_coin: Vec<u64>,
    pub out_energy: Vec<u64>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct AuctionResult {
    pub clearing_price: u64,
    pub total_energy_traded: u64,
    pub qualified_buyers: Vec<Participant>,
    pub qualified_sellers: Vec<Participant>,
    pub auction_successful: bool,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct AuctionScenario {
    pub scenario_name: String,
    pub description: String,
    pub expected_clearing_price: u64,
    pub expected_total_energy_traded: u64,
    pub participants: Vec<Participant>,
}

fn main() {
    // Initialize tracing. In order to view logs, run `RUST_LOG=info cargo run`
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::filter::EnvFilter::from_default_env())
        .init();

    println!("\x1b[36mRISC Zero Double Auction System\x1b[0m");
    println!("{}", "═".repeat(50));
    
    // Get scenario file from command line arguments
    let args: Vec<String> = env::args().collect();
    let scenario_file = if args.len() > 1 {
        &args[1]
    } else {
        // Default to sample scenario if no file specified
        "../sample_scenario.json"
    };
    
    // Load scenario from JSON file
    match load_scenario_from_file(scenario_file) {
        Ok(scenario) => {
            println!("\n▸ \x1b[36mScenario Loading\x1b[0m");
            print_tree_item(false, "Scenario name", &scenario.scenario_name, "");
            print_tree_item(false, "Description", &scenario.description, "");
            print_tree_item(true, "Participants", &format!("{} loaded", scenario.participants.len()), "");
            
            // Convert scenario to participants vector
            let participants = scenario.participants.clone();
            
            // Run the auction scenario
            if let Err(e) = run_auction_scenario(&scenario.scenario_name, participants) {
                eprintln!("❌ Auction scenario failed: {}", e);
                std::process::exit(1);
            }
        },
        Err(e) => {
            eprintln!("\x1b[31m✗ Failed to load scenario from {}: {}\x1b[0m", scenario_file, e);
            eprintln!("Provide a valid scenario JSON file (e.g., risc0_example/sample_scenario.json).");
            std::process::exit(1);
        }
    }
}

fn load_scenario_from_file(filename: &str) -> Result<AuctionScenario, Box<dyn std::error::Error>> {
    // Try to read from the specified path
    let content = fs::read_to_string(filename)?;
    let scenario: AuctionScenario = serde_json::from_str(&content)?;
    Ok(scenario)
}


fn run_auction_scenario(_name: &str, mut participants: Vec<Participant>) -> Result<(), Box<dyn std::error::Error>> {
    // Step 1: Display initial state
    println!("\n▸ \x1b[36mInitial Market State\x1b[0m");
    
    let mut buyers = Vec::new();
    let mut sellers = Vec::new();
    
    for p in &participants {
        if p.role == 0 { buyers.push(p); } else { sellers.push(p); }
    }
    
    // Show buyers first
    if !buyers.is_empty() {
        println!("├─ \x1b[32mBuyers\x1b[0m");
        for (i, p) in buyers.iter().enumerate() {
            let is_last_buyer = i == buyers.len() - 1 && sellers.is_empty();
            let prefix = if is_last_buyer { "└─" } else { "├─" };
            println!("│  {} ID{:02} → {} coins/unit, qty: {}, balance: {} coins, {} energy", 
                     prefix, p.id, p.price, p.quantity, p.in_coin, p.in_energy);
        }
    }
    
    // Show sellers
    if !sellers.is_empty() {
        let prefix = if sellers.len() == 1 { "└─" } else { "├─" };
        println!("{} \x1b[33mSellers\x1b[0m", prefix);
        for (i, p) in sellers.iter().enumerate() {
            let is_last = i == sellers.len() - 1;
            let sub_prefix = if is_last { "   └─" } else { "   ├─" };
            println!("{}ID{:02} → {} coins/unit, qty: {}, balance: {} coins, {} energy", 
                     sub_prefix, p.id, p.price, p.quantity, p.in_coin, p.in_energy);
        }
    }
    
    // Step 2: Perform the auction outside the circuit
    let auction_result = perform_double_auction(&mut participants);
    
    // Step 3: Display detailed auction results
    display_auction_results(&auction_result, &participants);
    
    // Step 4: Create input for ZKP verification
    let auction_input = AuctionInput {
        participants: participants.clone(),
        expected_clearing_price: auction_result.clearing_price,
        expected_total_energy_traded: auction_result.total_energy_traded,
    };
    
    // Step 4: Run ZKP verification 
    println!("\n▸ \x1b[36mZKP Generation\x1b[0m");
    
    let env = ExecutorEnv::builder()
        .write(&auction_input)
        .unwrap()
        .build()
        .unwrap();

    let prover = default_prover();
    let succinct_opts = ProverOpts::succinct();
    
    print_tree_item(false, "RISC Zero proof generation", "STARTED", "");
    let prove_info = prover
        .prove_with_opts(env, DOUBLE_AUCTION_ELF, &succinct_opts)
        .unwrap();

    let receipt = prove_info.receipt;
    let pj: PublicJournal = receipt.journal.decode().unwrap();
    
    // Verify the receipt
    receipt.verify(DOUBLE_AUCTION_ID).unwrap();
    print_tree_item(false, "Public journal validation", &format!("Clearing price: {}, Arrays: {}", pj.clearing_price, pj.in_coin.len()), "");
    
    // Extract c0 and c1 from the receipt claim digest
    extract_and_display_c0_c1(&receipt);
    
    // Demonstrate manual claim digest computation from JSON file
    demonstrate_claim_digest_from_json_and_journal(&pj);
    
    // Validate journal binding (mimics what we'll do in gnark circuit)
    validate_journal_binding(&receipt, &pj);
    
    // Save receipt to file for gnark circuit integration
    save_receipt_to_file(&receipt, &pj)?;
    
    // Generate input.json for Groth16 conversion
    match &receipt.inner {
        InnerReceipt::Succinct(succinct_receipt) => {
            match identity_p254(succinct_receipt) {
                Ok(identity_receipt) => {
                    let seal_bytes: Vec<u8> = identity_receipt.seal.iter()
                        .flat_map(|&x| x.to_le_bytes())
                        .collect();
                    
                    match std::fs::File::create("input.json") {
                        Ok(output_file) => {
                            let cursor = std::io::Cursor::new(&seal_bytes);
                            match seal_to_json(cursor, output_file) {
                                Ok(()) => {
                                    print_tree_item(true, "Groth16 input generation", "COMPLETED", 
                                                  &format!("{} bytes", seal_bytes.len()));
                                },
                                Err(e) => {
                                    print_tree_item(true, "Groth16 input generation", "FAILED", &e.to_string());
                                }
                            }
                        },
                        Err(e) => {
                            print_tree_item(true, "Groth16 input generation", "FAILED", &e.to_string());
                        }
                    }
                },
                Err(e) => {
                    print_tree_item(true, "Identity p254 conversion", "FAILED", &e.to_string());
                }
            }
        },
        _ => {
            print_tree_item(true, "Succinct receipt", "NOT AVAILABLE", "");
        }
    }
    
    println!();
    Ok(())
}

fn perform_double_auction(participants: &mut [Participant]) -> AuctionResult {
    // Create cloned vectors for sorting and analysis (avoids borrowing issues)
    let mut buyers: Vec<Participant> = participants
        .iter()
        .filter(|p| p.role == 0) // BUY
        .cloned()
        .collect();
        
    let mut sellers: Vec<Participant> = participants
        .iter()
        .filter(|p| p.role == 1) // SELL
        .cloned()
        .collect();
    
    // Sort buyers (descending by price) and sellers (ascending by price)
    buyers.sort_by(|a, b| {
        match b.price.cmp(&a.price) {
            std::cmp::Ordering::Equal => a.id.cmp(&b.id),
            other => other,
        }
    }); // Desc by price, tie-break by id asc
    sellers.sort_by(|a, b| {
        match a.price.cmp(&b.price) {
            std::cmp::Ordering::Equal => a.id.cmp(&b.id),
            other => other,
        }
    }); // Asc by price, tie-break by id asc
    
    // Create references for clearing rule
    let buyer_refs: Vec<&Participant> = buyers.iter().collect();
    let seller_refs: Vec<&Participant> = sellers.iter().collect();

    // Uniform marginal-crossing clearing
    let pstar_opt = find_uniform_clearing_host(&buyer_refs, &seller_refs);
    
    if pstar_opt.is_none() {
        // No intersection - no trading occurs, balances remain unchanged
        for participant in participants.iter_mut() {
            participant.out_coin = participant.in_coin;
            participant.out_energy = participant.in_energy;
        }
        return AuctionResult {
            clearing_price: 0,
            total_energy_traded: 0,
            qualified_buyers: Vec::new(),
            qualified_sellers: Vec::new(),
            auction_successful: false,
        };
    }
    
    let (p_star, b_marg, a_marg) = pstar_opt.unwrap();
    let clearing_price = (b_marg + a_marg) / 2; // average

    // Guard against zero clearing price to avoid division by zero
    if clearing_price == 0 {
        for participant in participants.iter_mut() {
            participant.out_coin = participant.in_coin;
            participant.out_energy = participant.in_energy;
        }
        return AuctionResult {
            clearing_price: 0,
            total_energy_traded: 0,
            qualified_buyers: Vec::new(),
            qualified_sellers: Vec::new(),
            auction_successful: false,
        };
    }

    // Determine qualified sets at p_star (NOT at p_c)
    let qualified_buyers: Vec<&Participant> = buyer_refs
        .iter()
        .copied()
        .filter(|b| b.price >= p_star)
        .collect();
    let qualified_sellers: Vec<&Participant> = seller_refs
        .iter()
        .copied()
        .filter(|s| s.price <= p_star)
        .collect();
    
    // Compute total demand and supply at p_star
    let _total_demand: u64 = qualified_buyers.iter().map(|b| b.quantity).sum();
    let _total_supply: u64 = qualified_sellers.iter().map(|s| s.quantity).sum();

    // Build allocation maps: id -> allocated energy
    use std::collections::HashMap;
    let mut alloc_by_id: HashMap<u32, u64> = HashMap::new();

    // Effective demand/supply with budget/stock caps at price p_c
    let mut eff_demand: u64 = 0;
    for b in &qualified_buyers {
        let max_afford = b.in_coin / clearing_price; // floor division
        let cap = if b.quantity < max_afford { b.quantity } else { max_afford };
        eff_demand = eff_demand.saturating_add(cap);
    }
    let mut eff_supply: u64 = 0;
    for s in &qualified_sellers {
        let cap = if s.quantity < s.in_energy { s.quantity } else { s.in_energy };
        eff_supply = eff_supply.saturating_add(cap);
    }
    let traded_total = eff_demand.min(eff_supply);

    if traded_total == 0 {
        for p in participants.iter_mut() {
            p.out_coin = p.in_coin;
            p.out_energy = p.in_energy;
        }
        return AuctionResult {
            clearing_price,
            total_energy_traded: 0,
            qualified_buyers: qualified_buyers.into_iter().cloned().collect(),
            qualified_sellers: qualified_sellers.into_iter().cloned().collect(),
            auction_successful: false,
        };
    }

    if eff_demand >= eff_supply {
        // Supply binding: sellers full (capped by stock); buyers priority by price, capped by budget & qty
        for s in &qualified_sellers {
            let cap = if s.quantity < s.in_energy { s.quantity } else { s.in_energy };
            alloc_by_id.insert(s.id, cap);
        }
        let mut remaining = traded_total;
        for b in &qualified_buyers {
            if remaining == 0 { break; }
            let max_afford = b.in_coin / clearing_price;
            let cap = b.quantity.min(max_afford);
            let take = if cap <= remaining { cap } else { remaining };
            alloc_by_id.insert(b.id, take);
            remaining -= take;
        }
    } else {
        // Demand binding: buyers full (capped by budget & qty); sellers priority by ask, capped by stock
        for b in &qualified_buyers {
            let max_afford = b.in_coin / clearing_price;
            let cap = b.quantity.min(max_afford);
            alloc_by_id.insert(b.id, cap);
        }
        let mut remaining = traded_total;
        for s in &qualified_sellers {
            if remaining == 0 { break; }
            let cap = s.quantity.min(s.in_energy);
            let take = if cap <= remaining { cap } else { remaining };
            alloc_by_id.insert(s.id, take);
            remaining -= take;
        }
    }

    // Update balances according to allocations
    for p in participants.iter_mut() {
        let allocated = *alloc_by_id.get(&p.id).unwrap_or(&0);
        if p.role == 0 { // BUY
            if allocated > 0 {
                p.out_coin = p.in_coin - (clearing_price * allocated);
                p.out_energy = p.in_energy + allocated;
            } else {
                p.out_coin = p.in_coin;
                p.out_energy = p.in_energy;
            }
        } else { // SELL
            if allocated > 0 {
                p.out_coin = p.in_coin + (clearing_price * allocated);
                p.out_energy = p.in_energy - allocated;
            } else {
                p.out_coin = p.in_coin;
                p.out_energy = p.in_energy;
            }
        }
    }

    AuctionResult {
        clearing_price,
        total_energy_traded: traded_total,
        qualified_buyers: qualified_buyers.into_iter().cloned().collect(),
        qualified_sellers: qualified_sellers.into_iter().cloned().collect(),
        auction_successful: clearing_price > 0 && traded_total > 0,
    }
}

fn demand_supply_at_price(buyers: &[&Participant], sellers: &[&Participant], p: u64) -> (u64, u64) {
    let demand: u64 = buyers.iter().filter(|b| b.price >= p).map(|b| b.quantity).sum();
    let supply: u64 = sellers.iter().filter(|s| s.price <= p).map(|s| s.quantity).sum();
    (demand, supply)
}

fn find_uniform_clearing_host(buyers: &[&Participant], sellers: &[&Participant]) -> Option<(u64, u64, u64)> {
    if buyers.is_empty() || sellers.is_empty() {
        return None;
    }

    // Discrete grid of candidate prices
    let mut prices: Vec<u64> = buyers.iter().map(|b| b.price).collect();
    prices.extend(sellers.iter().map(|s| s.price));
    prices.sort();
    prices.dedup();

    // Find p* = smallest p where S(p) >= D(p)
    let mut p_star: Option<u64> = None;
    for &p in &prices {
        let (d, s) = demand_supply_at_price(buyers, sellers, p);
        if s >= d {
            p_star = Some(p);
            break;
        }
    }

    let p_star = match p_star { Some(v) => v, None => return None };

    // Determine marginals at p*
    let mut qualified_buyers: Vec<&Participant> = buyers.iter().copied().filter(|b| b.price >= p_star).collect();
    let mut qualified_sellers: Vec<&Participant> = sellers.iter().copied().filter(|s| s.price <= p_star).collect();
    if qualified_buyers.is_empty() || qualified_sellers.is_empty() { return None; }
    qualified_buyers.sort_by(|a, b| b.price.cmp(&a.price));
    qualified_sellers.sort_by(|a, b| a.price.cmp(&b.price));

    let b_marg = qualified_buyers.last().unwrap().price;
    let a_marg = qualified_sellers.last().unwrap().price;

    Some((p_star, b_marg, a_marg))
}

// Display auction results in a clean, tree-style format matching the Go codebase
fn display_auction_results(auction_result: &AuctionResult, participants: &[Participant]) {
    println!("\n▸ \x1b[36mAuction Results\x1b[0m");
    
    if auction_result.clearing_price > 0 {
        // Print basic auction summary
        print_tree_item(false, "Market Status", "CLEARED", "");
        print_tree_item(false, "Clearing Price", &format!("{} coins/unit", auction_result.clearing_price), "");
        print_tree_item(false, "Volume Traded", &format!("{} energy units", auction_result.total_energy_traded), "");
        print_tree_item(true, "Market Participants", &format!("{} buyers, {} sellers qualified", 
                       auction_result.qualified_buyers.len(), auction_result.qualified_sellers.len()), "");
        
        // Separate buyers and sellers who actually traded
        let mut traded_buyers = Vec::new();
        let mut traded_sellers = Vec::new();
        let mut non_traded = Vec::new();
        
        for p in participants {
            let energy_change = p.out_energy as i64 - p.in_energy as i64;
            if energy_change != 0 {
                if p.role == 0 { // BUY
                    traded_buyers.push(p);
                } else { // SELL
                    traded_sellers.push(p);
                }
            } else {
                non_traded.push(p);
            }
        }
        
        // Display trading summary
        if !traded_buyers.is_empty() || !traded_sellers.is_empty() {
            println!("\n▸ \x1b[36mTrading Summary\x1b[0m");
            
            // Show buyers who traded
            if !traded_buyers.is_empty() {
                println!("├─ \x1b[32mBuyers (Energy Acquired)\x1b[0m");
                for (i, p) in traded_buyers.iter().enumerate() {
                    let energy_acquired = p.out_energy as i64 - p.in_energy as i64;
                    let coins_spent = p.in_coin as i64 - p.out_coin as i64;
                    let is_last_buyer = i == traded_buyers.len() - 1 && traded_sellers.is_empty();
                    let prefix = if is_last_buyer { "└─" } else { "├─" };
                    println!("│  {} ID{:02} → +{} energy, -{} coins @ {} coins/unit", 
                             prefix, p.id, energy_acquired, coins_spent, auction_result.clearing_price);
                }
            }
            
            // Show sellers who traded
            if !traded_sellers.is_empty() {
                let prefix = if traded_sellers.len() == 1 { "└─" } else { "├─" };
                println!("{} \x1b[33mSellers (Energy Sold)\x1b[0m", prefix);
                for (i, p) in traded_sellers.iter().enumerate() {
                    let energy_sold = p.in_energy as i64 - p.out_energy as i64;
                    let coins_earned = p.out_coin as i64 - p.in_coin as i64;
                    let is_last = i == traded_sellers.len() - 1;
                    let sub_prefix = if is_last { "   └─" } else { "   ├─" };
                    println!("{}ID{:02} → -{} energy, +{} coins @ {} coins/unit", 
                             sub_prefix, p.id, energy_sold, coins_earned, auction_result.clearing_price);
                }
            }
        }
        
        // Show non-trading participants
        if !non_traded.is_empty() {
            println!("\n▸ \x1b[90mNon-Trading Participants\x1b[0m");
            for (i, p) in non_traded.iter().enumerate() {
                let role_str = if p.role == 0 { "BUY" } else { "SELL" };
                let reason = if p.role == 0 {
                    if p.price < auction_result.clearing_price {
                        "bid too low"
                    } else {
                        "insufficient funds"
                    }
                } else {
                    if p.price > auction_result.clearing_price {
                        "ask too high"
                    } else {
                        "allocation filled"
                    }
                };
                let is_last = i == non_traded.len() - 1;
                let prefix = if is_last { "└─" } else { "├─" };
                println!("{} ID{:02} ({}) → {} @ {} coins/unit", 
                         prefix, p.id, role_str, reason, p.price);
            }
        }
        
    } else {
        print_tree_item(false, "Market Status", "NO CLEARING", "");
        print_tree_item(true, "Reason", "No price intersection found", "");
    }
    
    // Balance summary
    println!("\n▸ \x1b[36mBalance Summary\x1b[0m");
    let mut _total_coin_flow = 0i64;
    let mut _total_energy_flow = 0i64;
    
    for (i, p) in participants.iter().enumerate() {
        let coin_change = p.out_coin as i64 - p.in_coin as i64;
        let energy_change = p.out_energy as i64 - p.in_energy as i64;
        _total_coin_flow += coin_change.abs();
        _total_energy_flow += energy_change.abs();
        
        let role_str = if p.role == 0 { "BUY" } else { "SELL" };
        let is_last = i == participants.len() - 1;
        let prefix = if is_last { "└─" } else { "├─" };
        
        if coin_change == 0 && energy_change == 0 {
            println!("{} ID{:02} ({:4}) → No change", prefix, p.id, role_str);
        } else {
            println!("{} ID{:02} ({:4}) → {} coins ({:+}), {} energy ({:+})", 
                     prefix, p.id, role_str, p.out_coin, coin_change, p.out_energy, energy_change);
        }
    }
    
    println!();
}

// Helper function to print tree-style items (simplified version of Go's printTreeItem)
fn print_tree_item(is_last: bool, description: &str, status: &str, extra: &str) {
    let prefix = if is_last { "└─" } else { "├─" };
    let desc_formatted = format!("{:<35}", description);
    
    if extra.is_empty() {
        println!("\x1b[90m{}\x1b[0m {} \x1b[32m{}\x1b[0m", prefix, desc_formatted, status);
    } else {
        println!("\x1b[90m{}\x1b[0m {} \x1b[32m{}\x1b[0m \x1b[90m{}\x1b[0m", prefix, desc_formatted, status, extra);
    }
}

// Extract c0 and c1 from RISC Zero receipt using the exact split_digest algorithm
fn extract_and_display_c0_c1(receipt: &risc0_zkvm::Receipt) {
    use risc0_zkvm::sha::Digestible;
    
    println!("\n▸ \x1b[36mc0/c1 Extraction for BitVM/Native Groth16\x1b[0m");
    
    // Get the claim digest from the receipt
    let claim_digest = receipt.claim().expect("Failed to get receipt claim").digest();
    print_tree_item(false, "Receipt claim digest", &format!("0x{}", hex::encode(claim_digest.as_bytes())), "");
    
    // Apply RISC Zero's exact split_digest algorithm
    match split_digest_risc0(claim_digest) {
        Ok((c0, c1)) => {
            let c0_hex = format!("0x{}", hex::encode(fr_to_bytes(&c0)));
            let c1_hex = format!("0x{}", hex::encode(fr_to_bytes(&c1)));
            
            print_tree_item(false, "c0 (first half of claim digest)", &c0_hex, "");
            print_tree_item(true, "c1 (second half of claim digest)", &c1_hex, "");
        },
        Err(e) => {
            print_tree_item(true, "c0/c1 extraction", "FAILED", &e.to_string());
        }
    }
}

// Debug function to try alternative encodings and find the correct one
fn debug_alternative_encodings(receipt: &risc0_zkvm::Receipt) {
    use sha2::{Sha256, Digest as _};
    use risc0_zkvm::sha::Digestible;
    
    let actual_claim_digest = receipt.claim().expect("Failed to get receipt claim").digest();
    let actual_bytes = actual_claim_digest.as_bytes();
    
    if let Ok(maybe_claim) = receipt.claim() {
        if let risc0_zkvm::MaybePruned::Value(claim) = maybe_claim {
            let tag = {
                let mut hasher = Sha256::new();
                hasher.update(b"risc0.ReceiptClaim");
                hasher.finalize()
            };
            
            let input_digest = claim.input.digest();
            let pre_state_digest = claim.pre.digest();
            let post_state_digest = claim.post.digest();
            let output_digest = claim.output.digest();
            
            // Try different combinations
            println!("   Trying different exit code encodings:");
            
            // Try with exit codes shifted by 24 bits (as in Solidity)
            let sys_exit = match &claim.exit_code {
                risc0_zkvm::ExitCode::Halted(code) => *code as u32,
                _ => 0u32,
            };
            
            // Test 1: Shifted exit codes with big-endian
            {
                let mut hasher = Sha256::new();
                hasher.update(&tag);
                hasher.update(input_digest.as_bytes());
                hasher.update(pre_state_digest.as_bytes());
                hasher.update(post_state_digest.as_bytes());
                hasher.update(output_digest.as_bytes());
                hasher.update(&(sys_exit << 24).to_be_bytes());
                hasher.update(&(0u32 << 24).to_be_bytes());
                hasher.update(&4u32.to_be_bytes());
                let result = hasher.finalize();
                if result.as_slice() == actual_bytes {
                    println!("   ✓ MATCH: Shifted << 24, big-endian");
                }
            }
            
            // Test 2: No shift, big-endian  
            {
                let mut hasher = Sha256::new();
                hasher.update(&tag);
                hasher.update(input_digest.as_bytes());
                hasher.update(pre_state_digest.as_bytes());
                hasher.update(post_state_digest.as_bytes());
                hasher.update(output_digest.as_bytes());
                hasher.update(&sys_exit.to_be_bytes());
                hasher.update(&0u32.to_be_bytes());
                hasher.update(&4u32.to_be_bytes());
                let result = hasher.finalize();
                if result.as_slice() == actual_bytes {
                    println!("   ✓ MATCH: No shift, big-endian");
                }
            }
            
            // Test 3: No len field
            {
                let mut hasher = Sha256::new();
                hasher.update(&tag);
                hasher.update(input_digest.as_bytes());
                hasher.update(pre_state_digest.as_bytes());
                hasher.update(post_state_digest.as_bytes());
                hasher.update(output_digest.as_bytes());
                hasher.update(&sys_exit.to_le_bytes());
                hasher.update(&0u32.to_le_bytes());
                // No length field
                let result = hasher.finalize();
                if result.as_slice() == actual_bytes {
                    println!("   ✓ MATCH: No shift, little-endian, no len field");
                }
            }
        }
    }
}

// Compute claim digest from raw values using standard sha2 crate instead of RISC Zero's
fn compute_claim_digest_from_raw_values(
    // Pre-execution state
    pre_pc: u32,
    pre_merkle_root: [u8; 32],
    
    // Post-execution state  
    post_pc: u32,
    post_merkle_root: [u8; 32],
    
    // Journal and assumptions
    journal_bytes: &[u8],
    assumptions_digest_bytes: [u8; 32],
    
    // Exit codes
    sys_exit: u32,
    user_exit: u32,
) -> risc0_zkvm::sha::Digest {
    use sha2::{Sha256 as Sha256Std, Digest as _};
    
    // Helper function to convert sha2 hash to RISC Zero Digest
    let to_risc0_digest = |hash: sha2::digest::Output<Sha256Std>| -> risc0_zkvm::sha::Digest {
        let bytes = hash.as_slice();
        let mut words = [0u32; 8];
        for i in 0..8 {
            let mut word_bytes = [0u8; 4];
            word_bytes.copy_from_slice(&bytes[i*4..(i+1)*4]);
            words[i] = u32::from_le_bytes(word_bytes);
        }
        risc0_zkvm::sha::Digest::new(words)
    };
    
    // Step 1: Compute the pre_state_digest
    // SystemState digest = tagged_struct("risc0.SystemState", &[merkle_root], &[pc])
    let pre_state_digest = {
        let tag = Sha256Std::digest(b"risc0.SystemState");
        let mut buf = Vec::new();
        buf.extend_from_slice(tag.as_slice());
        buf.extend_from_slice(&pre_merkle_root);
        buf.extend_from_slice(&pre_pc.to_le_bytes());
        let down_count: u16 = 1; // One digest (merkle_root)
        buf.extend_from_slice(&down_count.to_le_bytes());
        to_risc0_digest(Sha256Std::digest(&buf))
    };
    
    // Step 2: Compute the post_state_digest
    let post_state_digest = {
        let tag = Sha256Std::digest(b"risc0.SystemState");
        let mut buf = Vec::new();
        buf.extend_from_slice(tag.as_slice());
        buf.extend_from_slice(&post_merkle_root);
        buf.extend_from_slice(&post_pc.to_le_bytes());
        let down_count: u16 = 1;
        buf.extend_from_slice(&down_count.to_le_bytes());
        to_risc0_digest(Sha256Std::digest(&buf))
    };
    
    // Step 3: Compute the journal_digest
    let journal_digest = to_risc0_digest(Sha256Std::digest(journal_bytes));
    
    // Step 4: Compute the output_digest
    // Output digest = tagged_struct("risc0.Output", &[journal_digest, assumptions_digest], &[])
    let output_digest = {
        let tag = Sha256Std::digest(b"risc0.Output");
        let mut buf = Vec::new();
        buf.extend_from_slice(tag.as_slice());
        buf.extend_from_slice(journal_digest.as_bytes());
        buf.extend_from_slice(&assumptions_digest_bytes);
        // No data array for Output
        let down_count: u16 = 2; // Two digests (journal, assumptions)
        buf.extend_from_slice(&down_count.to_le_bytes());
        to_risc0_digest(Sha256Std::digest(&buf))
    };
    
    // Step 5: Input digest is always zero for now
    let input_digest = risc0_zkvm::sha::Digest::new([0u32; 8]);
    
    // Step 6: Compute the final claim digest
    // ReceiptClaim digest = tagged_struct("risc0.ReceiptClaim", 
    //                                     &[input, pre, post, output],
    //                                     &[sys_exit, user_exit])
    let claim_digest = {
        let tag = Sha256Std::digest(b"risc0.ReceiptClaim");
        let mut buf = Vec::new();
        buf.extend_from_slice(tag.as_slice());
        buf.extend_from_slice(input_digest.as_bytes());
        buf.extend_from_slice(pre_state_digest.as_bytes());
        buf.extend_from_slice(post_state_digest.as_bytes());
        buf.extend_from_slice(output_digest.as_bytes());
        buf.extend_from_slice(&sys_exit.to_le_bytes());
        buf.extend_from_slice(&user_exit.to_le_bytes());
        let down_count: u16 = 4; // Four digests
        buf.extend_from_slice(&down_count.to_le_bytes());
        to_risc0_digest(Sha256Std::digest(&buf))
    };
    
    println!("\n   [RAW VALUES CLAIM COMPUTATION]:");
    println!("     Pre-state: pc={}, merkle_root=0x{}", pre_pc, hex::encode(&pre_merkle_root));
    println!("     Post-state: pc={}, merkle_root=0x{}", post_pc, hex::encode(&post_merkle_root));
    println!("     Journal: {} bytes, digest=0x{}", journal_bytes.len(), hex::encode(journal_digest.as_bytes()));
    println!("     Assumptions digest: 0x{}", hex::encode(&assumptions_digest_bytes));
    println!("     Exit codes: sys={}, user={}", sys_exit, user_exit);
    println!("\n     Intermediate digests:");
    println!("       input_digest: 0x{}", hex::encode(input_digest.as_bytes()));
    println!("       pre_state_digest: 0x{}", hex::encode(pre_state_digest.as_bytes()));
    println!("       post_state_digest: 0x{}", hex::encode(post_state_digest.as_bytes()));
    println!("       output_digest: 0x{}", hex::encode(output_digest.as_bytes()));
    println!("\n     Final claim_digest: 0x{}", hex::encode(claim_digest.as_bytes()));
    
    claim_digest
}

