// Validate journal binding constraint (mimics gnark circuit implementation)
fn validate_journal_binding(receipt: &risc0_zkvm::Receipt, journal: &PublicJournal) {
    use risc0_zkvm::sha::Digestible;
    
    println!("\n▸ \x1b[36mJournal Binding Validation (Gnark Circuit Simulation)\x1b[0m");
    
    // Step 1: Get the actual journal bytes from RISC Zero receipt
    let actual_journal_bytes = &receipt.journal.bytes;
    let actual_journal_digest = {
        use sha2::{Sha256, Digest as _};
        let mut hasher = Sha256::new();
        hasher.update(actual_journal_bytes);
        hasher.finalize().to_vec()
    };
    print_tree_item(false, "Actual journal bytes digest", &format!("0x{}", hex::encode(&actual_journal_digest)), "");
    
    // Step 2: Extract RISC Zero journal digest from receipt
    let risc0_journal_digest = receipt.journal.digest();
    print_tree_item(false, "RISC Zero journal digest", &format!("0x{}", hex::encode(risc0_journal_digest.as_bytes())), "");
    
    // Step 3: Compute circuit-side journal digest (what we'll do in gnark)
    let circuit_journal_digest = compute_circuit_journal_digest(journal);
    print_tree_item(false, "Circuit computed journal digest", &format!("0x{}", hex::encode(&circuit_journal_digest)), "");
    
    // Step 4: Compute claim digest using our computed journal digest and receipt data
    let computed_claim_digest = match compute_claim_digest_from_receipt_and_journal_digest(receipt, &circuit_journal_digest) {
        Ok(digest) => digest,
        Err(e) => {
            print_tree_item(false, "Computed claim digest", "FAILED", &e.to_string());
            return;
        }
    };
    
    // Get the actual claim digest from receipt
    let actual_claim_digest = receipt.claim().expect("Failed to get receipt claim").digest();
    
    print_tree_item(false, "Computed claim digest", &format!("0x{}", hex::encode(computed_claim_digest.as_bytes())), "");
    print_tree_item(false, "Actual claim digest", &format!("0x{}", hex::encode(actual_claim_digest.as_bytes())), "");
    
    // Step 4: Compare all three digests to understand the relationships
    println!("\n   \x1b[93m[DEBUG] Digest Analysis:\x1b[0m");
    println!("   Actual journal bytes digest: 0x{}", hex::encode(&actual_journal_digest));
    println!("   RISC Zero journal digest:    0x{}", hex::encode(risc0_journal_digest.as_bytes()));
    println!("   Circuit computed digest:     0x{}", hex::encode(&circuit_journal_digest));
    println!("   Journal bytes length: {} bytes", actual_journal_bytes.len());
    
    // Export journal data for Python verification
    println!("\n   \x1b[96m[PYTHON DATA] Journal values for verification:\x1b[0m");
    println!("   clearing_price: {}", journal.clearing_price);
    println!("   in_coin: {:?}", journal.in_coin);
    println!("   in_energy: {:?}", journal.in_energy);
    println!("   out_coin: {:?}", journal.out_coin);
    println!("   out_energy: {:?}", journal.out_energy);
    
    // Check which digest matches what
    let actual_matches_risc0 = actual_journal_digest == risc0_journal_digest.as_bytes();
    let circuit_matches_risc0 = circuit_journal_digest == risc0_journal_digest.as_bytes();
    let circuit_matches_actual = circuit_journal_digest == actual_journal_digest;
    let computed_claim_matches_actual = computed_claim_digest.as_bytes() == actual_claim_digest.as_bytes();
    
    print_tree_item(false, "Actual bytes digest == RISC0 digest", if actual_matches_risc0 { "✓ MATCH" } else { "✗ NO MATCH" }, "");
    print_tree_item(false, "Circuit digest == RISC0 digest", if circuit_matches_risc0 { "✓ MATCH" } else { "✗ NO MATCH" }, "");
    print_tree_item(false, "Circuit digest == Actual digest", if circuit_matches_actual { "✓ MATCH" } else { "✗ NO MATCH" }, "");
    print_tree_item(true, "Computed claim == Actual claim", if computed_claim_matches_actual { "✓ MATCH" } else { "✗ NO MATCH" }, "");
    
    // Final binding constraint result
    if circuit_matches_risc0 {
        println!("\n✅ \x1b[32mJournal binding constraint VALID!\x1b[0m");
    } else {
        println!("\n❌ \x1b[31mJournal binding constraint INVALID!\x1b[0m");
        if circuit_matches_actual && !actual_matches_risc0 {
            println!("   \x1b[33m→ RISC Zero uses a different digest than SHA-256 of raw bytes!\x1b[0m");
        }
    }
}

// Compute journal digest exactly as we would in the gnark circuit
fn compute_circuit_journal_digest(journal: &PublicJournal) -> Vec<u8> {
    use sha2::{Sha256, Digest as _};
    
    // Serialize journal in the same format that RISC Zero uses
    // This must match risc0_zkvm's internal serialization exactly
    let serialized = serialize_journal_risc0_format(journal);
    
    // Compute SHA-256 (same as RISC Zero)
    let mut hasher = Sha256::new();
    hasher.update(&serialized);
    hasher.finalize().to_vec()
}

// Create a new function that computes claim digest exactly as RISC Zero does internally
fn compute_manual_claim_digest(receipt: &risc0_zkvm::Receipt) -> Result<risc0_zkvm::sha::Digest, Box<dyn std::error::Error>> {
    use risc0_zkvm::sha::{Digestible, Sha256};
    
    // Get the claim from receipt and extract the actual ReceiptClaim from MaybePruned
    let maybe_claim = receipt.claim()?;
    let claim = match maybe_claim {
        risc0_zkvm::MaybePruned::Value(claim) => claim,
        risc0_zkvm::MaybePruned::Pruned(_) => return Err("Receipt claim is pruned, cannot extract fields".into()),
    };
    
    // RISC Zero's claim digest computation uses the tagged_struct! macro
    // Based on the source code, tagged_struct does:
    // 1. Computes TAG = sha256("risc0.ReceiptClaim")  
    // 2. Hashes: TAG || down[0] || down[1] || ... || data[0] || data[1] || ... || len(down)
    // where down = [input, pre, post, output] digests (4 elements)
    // and data = [sys_exit, user_exit] as u32 values
    
    // TAG = sha256("risc0.ReceiptClaim") using RISC Zero's SHA implementation
    let tag_digest = risc0_zkvm::sha::Impl::hash_bytes(b"risc0.ReceiptClaim");
    
    // Extract claim fields from the actual ReceiptClaim
    let input_digest = claim.input.digest();
    let pre_state_digest = claim.pre.digest(); 
    let post_state_digest = claim.post.digest();
    let output_digest = claim.output.digest();
    
    // Use RISC Zero's own into_pair() method directly
    let (sys_exit, user_exit) = claim.exit_code.into_pair();
    
    // Debug: Print all the components before hashing
    println!("\n   [MANUAL CLAIM DIGEST COMPUTATION]:");
    println!("     tag_digest: 0x{}", hex::encode(tag_digest.as_bytes()));
    println!("     input_digest: 0x{}", hex::encode(input_digest.as_bytes()));
    println!("     pre_state_digest: 0x{}", hex::encode(pre_state_digest.as_bytes()));
    println!("     post_state_digest: 0x{}", hex::encode(post_state_digest.as_bytes()));
    println!("     output_digest: 0x{}", hex::encode(output_digest.as_bytes()));
    println!("     sys_exit: {} (0x{:08x})", sys_exit, sys_exit);
    println!("     user_exit: {} (0x{:08x})", user_exit, user_exit);
    
    // Exactly match RISC Zero's tagged_struct implementation from risc0/binfmt/src/hash.rs
    // Build the byte buffer exactly as RISC Zero does
    let mut all = Vec::<u8>::new();
    
    // 1. Add tag digest
    all.extend_from_slice(tag_digest.as_bytes());
    
    // 2. Add "down" array (4 digests, each 32 bytes) in order
    all.extend_from_slice(input_digest.as_bytes());
    all.extend_from_slice(pre_state_digest.as_bytes());
    all.extend_from_slice(post_state_digest.as_bytes());
    all.extend_from_slice(output_digest.as_bytes());
    
    // 3. Add "data" array (exit codes as u32 values in little-endian)
    all.extend_from_slice(&sys_exit.to_le_bytes());
    all.extend_from_slice(&user_exit.to_le_bytes());
    
    // 4. Add down_count as u16 (not u32!) in little-endian
    let down_count: u16 = 4;
    all.extend_from_slice(&down_count.to_le_bytes());
    
    // Compute the final hash using RISC Zero's SHA implementation
    let result = risc0_zkvm::sha::Impl::hash_bytes(&all);
    Ok(*result)
}

// Keep the old function for backwards compatibility but have it call the new one
fn compute_claim_digest_from_receipt_and_journal_digest(receipt: &risc0_zkvm::Receipt, _journal_digest: &[u8]) -> Result<risc0_zkvm::sha::Digest, Box<dyn std::error::Error>> {
    // Note: We ignore the journal_digest parameter and compute the claim digest directly from the receipt
    // This is because RISC Zero uses the output digest (which includes journal + assumptions), not just the journal digest
    compute_manual_claim_digest(receipt)
}

// Helper function to convert [u8; 32] to [u32; 8] for RISC Zero Digest
fn bytes_to_u32_array(bytes: &[u8]) -> Result<[u32; 8], Box<dyn std::error::Error>> {
    if bytes.len() != 32 {
        return Err(format!("Expected 32 bytes, got {}", bytes.len()).into());
    }
    
    let mut words = [0u32; 8];
    for (i, chunk) in bytes.chunks(4).enumerate() {
        if i < 8 {
            let mut word_bytes = [0u8; 4];
            word_bytes.copy_from_slice(chunk);
            words[i] = u32::from_be_bytes(word_bytes); // RISC Zero uses big-endian for digest words
        }
    }
    Ok(words)
}

// Serialize journal in RISC Zero's exact format (u32-word based)
fn serialize_journal_risc0_format(journal: &PublicJournal) -> Vec<u8> {
    // RISC Zero serializes to u32 words - implement exactly like their serializer
    let mut words: Vec<u32> = Vec::new();
    
    // Serialize clearing_price (u64 -> 2 words)
    let price_bytes = journal.clearing_price.to_le_bytes();
    words.push(u32::from_le_bytes([price_bytes[0], price_bytes[1], price_bytes[2], price_bytes[3]]));
    words.push(u32::from_le_bytes([price_bytes[4], price_bytes[5], price_bytes[6], price_bytes[7]]));
    
    // Serialize Vec<u64> arrays
    serialize_u64_vec_to_words(&mut words, &journal.in_coin);
    serialize_u64_vec_to_words(&mut words, &journal.in_energy);
    serialize_u64_vec_to_words(&mut words, &journal.out_coin);
    serialize_u64_vec_to_words(&mut words, &journal.out_energy);
    
    // Convert u32 words to bytes (little-endian)
    let mut bytes = Vec::new();
    for word in words {
        bytes.extend_from_slice(&word.to_le_bytes());
    }
    bytes
}

// Helper to serialize Vec<u64> to u32 words (RISC Zero format)
fn serialize_u64_vec_to_words(words: &mut Vec<u32>, vec: &[u64]) {
    // Length as u32
    words.push(vec.len() as u32);
    
    // Each u64 as 2 u32 words
    for &val in vec {
        let bytes = val.to_le_bytes();
        words.push(u32::from_le_bytes([bytes[0], bytes[1], bytes[2], bytes[3]]));
        words.push(u32::from_le_bytes([bytes[4], bytes[5], bytes[6], bytes[7]]));
    }
}

// RISC Zero's exact split_digest algorithm from risc0/groth16/src/verifier.rs:302-310
fn split_digest_risc0(d: risc0_zkvm::sha::Digest) -> Result<(ark_bn254::Fr, ark_bn254::Fr), Box<dyn std::error::Error>> {
    // Step 1: Convert to big-endian (RISC Zero line 303)
    let big_endian: Vec<u8> = d.as_bytes().iter().rev().cloned().collect();
    
    // Step 2: Split at middle (RISC Zero line 304-305)  
    let middle = big_endian.len() / 2;
    let (b, a) = big_endian.split_at(middle);
    
    // Step 3: Convert each half to BN254 field element (RISC Zero lines 306-309)
    let c0 = fr_from_bytes(&from_u256_hex(&hex::encode(a))?)?;  // First half -> c0
    let c1 = fr_from_bytes(&from_u256_hex(&hex::encode(b))?)?;  // Second half -> c1
    
    Ok((c0, c1))
}

// Helper functions matching RISC Zero's implementation
fn fr_from_bytes(scalar: &[u8]) -> Result<ark_bn254::Fr, Box<dyn std::error::Error>> {
    let scalar: Vec<u8> = scalar.iter().rev().cloned().collect();
    use ark_serialize::CanonicalDeserialize;
    ark_bn254::Fr::deserialize_uncompressed(&*scalar).map_err(|e| format!("Deserialization error: {}", e).into())
}

fn from_u256_hex(value: &str) -> Result<Vec<u8>, Box<dyn std::error::Error>> {
    Ok(to_fixed_array(hex::decode(value)?).to_vec())
}

fn to_fixed_array(input: Vec<u8>) -> [u8; 32] {
    let mut fixed_array = [0u8; 32];
    let start = core::cmp::max(32, input.len()) - core::cmp::min(32, input.len());
    fixed_array[start..].copy_from_slice(&input[input.len().saturating_sub(32)..]);
    fixed_array
}

fn fr_to_bytes(fr: &ark_bn254::Fr) -> Vec<u8> {
    use ark_serialize::CanonicalSerialize;
    let mut buffer = Vec::new();
    fr.serialize_uncompressed(&mut buffer).unwrap();
    buffer.reverse(); // Convert to big-endian
    buffer
}

// Save receipt and journal data for gnark circuit integration
fn save_receipt_to_file(receipt: &risc0_zkvm::Receipt, journal: &PublicJournal) -> Result<(), Box<dyn std::error::Error>> {
    use risc0_zkvm::sha::Digestible;
    use std::fs::File;
    use std::io::BufWriter;
    
    println!("\n▸ \x1b[36mSaving Receipt for Gnark Integration\x1b[0m");
    
    // 1. Save complete receipt (bincode for efficiency)
    let receipt_bytes = bincode::serialize(&receipt)?;
    std::fs::write("risc0_receipt.bin", &receipt_bytes)?;
    print_tree_item(false, "Receipt binary file", "risc0_receipt.bin", &format!("{} bytes", receipt_bytes.len()));
    
    // 2. Save receipt as JSON (human readable)
    let receipt_file = File::create("risc0_receipt.json")?;
    let writer = BufWriter::new(receipt_file);
    serde_json::to_writer_pretty(writer, &receipt)?;
    print_tree_item(false, "Receipt JSON file", "risc0_receipt.json", "");
    
    // 3. Save journal digest and data for gnark public inputs
    let journal_digest = receipt.journal.digest();
    let gnark_data = serde_json::json!({
        "journal_digest": format!("0x{}", hex::encode(journal_digest.as_bytes())),
        "journal_digest_bytes": journal_digest.as_bytes().to_vec(),
        "clearing_price": journal.clearing_price,
        "in_coin": journal.in_coin,
        "in_energy": journal.in_energy,
        "out_coin": journal.out_coin,
        "out_energy": journal.out_energy,
        "participants": journal.in_coin.len(),
        "description": "RISC Zero auction journal data for gnark circuit binding constraint"
    });
    
    let gnark_file = File::create("gnark_inputs.json")?;
    let writer = BufWriter::new(gnark_file);
    serde_json::to_writer_pretty(writer, &gnark_data)?;
    print_tree_item(true, "Gnark inputs file", "gnark_inputs.json", "Journal digest + auction data");
    
    println!("\n✅ \x1b[32mFiles ready for gnark integration!\x1b[0m");
    println!("   Use journal_digest: {}", format!("0x{}", hex::encode(journal_digest.as_bytes())));
    
    Ok(())
}
